// Generates one static HTML file per event (event-<id>.html, at repo root) so link
// previews (WhatsApp, etc.) get that event's real title/description/poster image baked
// into the <head> — something a single client-side-rendered template can't provide,
// since crawlers only read the initial HTML, never the JS-rendered content.
//
// The generated page still loads assets/js/event.js to render the full interactive
// content for human visitors (via <body data-event-id="...">) — only the <head> meta
// is duplicated per event, everything else stays driven by events.json as normal.
//
// Regenerated by .github/workflows/build-event-pages.yml whenever events.json changes;
// can also be run locally with `node .github/scripts/build-event-pages.js`.
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const EVENTS_PATH = path.join(ROOT, "assets", "data", "events.json");
const SITE_URL = "https://anirudhpv.github.io/no-pressure-improv";
const GA_ID = "G-RQR399VMR1";

const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const DOW = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

function ordinal(n){ const s=["th","st","nd","rd"], v=n%100; return n+(s[(v-20)%10]||s[v]||s[0]); }
function esc(s){ return String(s).replace(/[&<>"]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }
function fmtWhen(e){
  const [y,m,d] = e.date.split("-").map(Number);
  const date = new Date(y, m-1, d);
  return `${DOW[date.getDay()]}, ${ordinal(d)} ${MONTH_NAMES[m-1]} ${y}`;
}

function pageHTML(e){
  const title = `${e.title} — No Pressure Improv`;
  const desc = `${e.title} · ${fmtWhen(e)} · ${e.venue} — No Pressure Improv, Bengaluru.`;
  const image = `${SITE_URL}/assets/images/${e.image || "logo.png"}`;
  const url = `${SITE_URL}/event-${e.id}.html`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<script async src="https://www.googletagmanager.com/gtag/js?id=${GA_ID}"></script>
<script src="assets/js/analytics.js"></script>
<title>${esc(title)}</title>
<meta name="description" content="${esc(desc)}">
<meta name="robots" content="noindex, nofollow, noarchive, nosnippet, noimageindex">
<meta property="og:type" content="website">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(desc)}">
<meta property="og:url" content="${esc(url)}">
<meta property="og:image" content="${esc(image)}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${esc(title)}">
<meta name="twitter:description" content="${esc(desc)}">
<meta name="twitter:image" content="${esc(image)}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700;12..96,800&family=Figtree:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap">
<link rel="icon" href="assets/images/logo.png">
<link rel="stylesheet" href="assets/css/base.css">
<link rel="stylesheet" href="assets/css/calendar.css">
<link rel="stylesheet" href="assets/css/event.css">
</head>
<body data-event-id="${esc(e.id)}">
<div class="wrap">
  <header class="top" id="site-header" data-include="partials/header.html"></header>

  <div class="event-page">
    <a class="back-link" href="calendar.html">← Back to calendar</a>
    <div id="eventContent">Loading…</div>
  </div>

  <footer id="site-footer" data-include="partials/footer.html"></footer>
</div>

<div class="lb" id="lb" role="dialog" aria-label="Enlarged image"><img alt=""></div>

<script src="assets/js/include.js"></script>
<script src="assets/js/event.js"></script>
</body>
</html>
`;
}

function main(){
  const events = JSON.parse(fs.readFileSync(EVENTS_PATH, "utf-8"));
  const validIds = new Set(events.map(e => e.id));

  // Remove stale pages for events that no longer exist (renamed/deleted ids).
  for (const file of fs.readdirSync(ROOT)){
    const m = file.match(/^event-(.+)\.html$/);
    if (m && !validIds.has(m[1])){
      fs.unlinkSync(path.join(ROOT, file));
      console.log(`Removed stale ${file}`);
    }
  }

  for (const e of events){
    const outPath = path.join(ROOT, `event-${e.id}.html`);
    fs.writeFileSync(outPath, pageHTML(e));
  }
  console.log(`Wrote ${events.length} event page(s).`);
}

main();
